mapper.insert:
insert into order_detail (id, name, image, order_id, dish_id, setmeal_id, dish_flavor, num, amount) select seq_order_detail.nextval, t.* from (
select #{item.name} as name, #{item.image} as image, #{item.orderId} as order_id, #{item.dishId} as dish_id, #{item.setmealId} as setmeal_id, #{item.dishFlavor} as dish_flavor, #{item.number} as num, #{item.amount} as amount from dual
) t
